import{_ as n,a as t,b as r,c as i,d as s,e as a,f as d,g,h as l,i as o,j as h,k as u,l as b,m as c,n as m,o as p,p as k,q as f,r as S,s as z,t as E,u as w,v as A,w as D,x as v,y as x}from"./chunks/industrial-switches.Cprwr02P.js";import{_ as B,o as W,c as G,a3 as L}from"./chunks/framework.BlfGB29P.js";const T=JSON.parse('{"title":"Industrie – Widgets","description":"Installation und Einstellungen des externen Industriepakets für Grafik Visual Studio.","frontmatter":{"title":"Industrie – Widgets","description":"Installation und Einstellungen des externen Industriepakets für Grafik Visual Studio."},"headers":[],"relativePath":"projects/grafik-visual-studio/industrial.md","filePath":"projects/grafik-visual-studio/industrial.md","lastUpdated":1792754903000}'),P={name:"projects/grafik-visual-studio/industrial.md"};function _(Z,e,y,F,R,V){return W(),G("div",null,[...e[0]||(e[0]=[L('<h1 id="industrie-–-widgets" tabindex="-1">Industrie – Widgets <a class="header-anchor" href="#industrie-–-widgets" aria-label="Permalink to &quot;Industrie – Widgets&quot;">​</a></h1><p>Das externe Widget-Paket <strong>Industrie 0.11.6</strong> enthält sechzehn Widgets: <strong>Gauge/Poti – 270°</strong>, <strong>Kippschalter – 1 bis 4</strong>, <strong>Wippschalter – 1 bis 4</strong>, <strong>LCD – 20×4</strong>, <strong>LCD – 16×2</strong>, <strong>Linear-Gauge / Schieberegler</strong> und <strong>Zählwerk</strong> in normaler und schmaler Ausführung, <strong>7-Segment – LED</strong>, <strong>16-Segment – LED</strong>, <strong>16-Segment – LCD</strong>, <strong>Industrie-Uhr – Nixie / LED / LCD</strong>, <strong>Industrie-Wetter – LCD / LED</strong>, <strong>Blindelement</strong> sowie <strong>Heizung – Kessel und Öltank</strong>. Industriestyle ergänzt Gehäuse, Schraubenköpfe und Rahmen. Das Heizungswidget mit der detaillierten Grafik benötigt <strong>Studio 0.1.253 oder neuer</strong>.</p><p><strong>Updatehinweis:</strong> Version 0.11.4 konnte wegen geänderter Widgetbeschriftungen nicht über eine bestehende Installation installiert werden. Verwende stattdessen <strong>0.11.5</strong> als lokale <code>.wg</code>-Datei; sie bewahrt die veröffentlichten Widgetverträge und Entitätsbindungen. Studio <strong>0.1.259</strong> zeigt die Vorlauf-Einstellungen unter der neuen Bezeichnung an, ohne gespeicherte Gruppenschlüssel zu ändern.</p><h2 id="bilder" tabindex="-1">Bilder <a class="header-anchor" href="#bilder" aria-label="Permalink to &quot;Bilder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Poti mit Strichskala</th><th>Gauge mit Farbring</th></tr></thead><tbody><tr><td><img src="'+n+'" alt="Industrie-Poti mit Strichskala und Wertanzeige unten"></td><td><img src="'+t+'" alt="Industrie-Gauge mit Farbring und Solarleistung in der Mitte"></td></tr><tr><td>Ohne Eingang: virtueller Drehregler mit negativem Skalenminimum und <strong>15 °C</strong> unterhalb des Knopfes.</td><td>Mit Eingang: <strong>823 W</strong> Solarleistung auf einer Skala von 0–1000 W, farbige Bereiche und mittige Wertanzeige.</td></tr></tbody></table><p>Die Bilder zeigen die Runtime mit Beispieldaten, keine Live-Messungen.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Alle Entitätsfelder des Sets besitzen eine <strong>…</strong>-Schaltfläche zum Öffnen der <strong>Home-Assistant-Entitätenauswahl</strong>. Gewünschte Entität suchen, auswählen und mit <strong>Einfügen</strong> in das aktive Feld übernehmen. Ab <strong>Studio 0.1.250</strong> gilt das auch für <strong>Eingang: Entität</strong> und <strong>Ausgang: Entität</strong> in jedem Kipp-/Wippschalterkanal. Die Auswahl wird dem jeweiligen Kanal zugeordnet. Für vorhandene Pakete genügt das Studio-Update.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/raw/master/ha_grafik_visual_studio/packages/industrial/ugso.industrial.wg" target="_blank" rel="noreferrer">Paketdatei herunterladen</a> und unter <strong>Einstellungen → Widget-Pakete → Lokal</strong> installieren. Zuerst Studio auf <strong>0.1.253 oder neuer</strong> aktualisieren, danach Paket <strong>0.11.3</strong> installieren. Für die detaillierte Grafik genügt das Studio-Update mit vorhandenem Paket 0.11.1/0.11.2. Anschließend den Browser mit <strong>Strg+F5</strong> neu laden. Das Paket ist optional, verwendet API 0.2 und enthält keinen ausführbaren Paketcode. Alle sechzehn bisherigen Widget-Definitionen bleiben beim Update erhalten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/industrial" target="_blank" rel="noreferrer">Quellcode und Paket-Anleitung auf GitHub</a></p><h2 id="heizung-–-kessel-und-oltank" tabindex="-1">Heizung – Kessel und Öltank <a class="header-anchor" href="#heizung-–-kessel-und-oltank" aria-label="Permalink to &quot;Heizung – Kessel und Öltank&quot;">​</a></h2><p><img src="'+r+'" alt="Detailliertes Heizungswidget mit dynamischen Temperaturen, zwei Pumpen, Brenner, Störung und Tankfüllstand"></p><p>Die detaillierte transparente PNG-Vorlage zeigt einen dunkelroten Heizkessel, zwei grüne Pumpen, blauen Brenner und Kupfertank nebeneinander. Temperaturen, Statusanzeigen, Warnsymbol, Tankfüllhöhe und Pfeile sind dynamische SVG-Elemente. Grafik und Anzeigen verwenden dasselbe Koordinatensystem mit den tatsächlichen Bildmaßen <strong>1683×935</strong> und skalieren gemeinsam. Dadurch bleiben die Anzeigen auch beim Ziehen oder Ändern der Größe am zugehörigen Bauteil.</p><p><strong>Breite:Höhe 7:4 Rasterfelder</strong>, mit den additiven Gehäuseabständen: bei 1 px Abstand mindestens <strong>460×262 px</strong>, voreingestellt <strong>908×518 px</strong>. Bestehende 4:6- und 6:4-Widgets wechseln beim Öffnen in dieses Format und behalten ihre Rasterzellengröße und Entitätszuordnungen. Die Grafik wird lokal mit Studio ausgeliefert. Die Abbildung zeigt lokale Testwerte.</p><table tabindex="0"><thead><tr><th>Anzeige</th><th>Entität und Einstellungen</th></tr></thead><tbody><tr><td>Vorlauftemperatur</td><td>Numerische Entität, ausblendbar, eigene Textfarbe</td></tr><tr><td>Rücklauftemperatur</td><td>Numerische Entität, ausblendbar, eigene Textfarbe; Anzeige unter dem orangefarbenen Rohr</td></tr><tr><td>Kessel-, Warmwasser-, Kaltwassertemperatur</td><td>Je eine numerische Entität und eigene Textfarbe</td></tr><tr><td>Heizkreispumpe, Zirkulationspumpe, Brenner</td><td>Je eine Boolean-Entität; Statusanzeige separat ausblendbar</td></tr><tr><td>Störung</td><td>Boolean-Entität; Warnsymbol neben Kesseltemperatur, ausblendbar</td></tr><tr><td>Tankfüllstand</td><td>Numerischer Sensor in Prozent <strong>0–100 %</strong>, Füllhöhe und Zahlenwert</td></tr></tbody></table><p>Alle <strong>zehn Entitäten</strong> besitzen die Home-Assistant-Auswahl. Boolean-Werte <code>on/off</code>, <code>true/false</code> und <code>1/0</code> werden erkannt; die sichtbare Beschriftung ist wählbar als <strong>EIN/AUS</strong>, <strong>ON/OFF</strong> oder <strong>1/0</strong>. Temperaturen übernehmen die Einheit der Entität und lassen sich unabhängig einfärben. Die Grundfarben entsprechen der Vorlage: rot für Temperaturen, orange für Rücklauf, blau für Kaltwasser, grün für eingeschalteten Status, gelb für Störung und rosa für Füllstand.</p><p>Ab <strong>Studio 0.1.260</strong> liegt der linke rote Anschluss höher. Der orange Rücklauf verläuft davor mit leichtem Knick parallel zum Anschluss am Kessel; sein Pfeil sitzt links und zeigt nach rechts zum Kessel. Unter <strong>Rücklauf</strong> sind Entität, Anzeige sichtbar, Textfarbe und Flusspfeil einstellbar. Bestehende Widgets erhalten die Eigenschaften durch das Studio-Update; <strong>Industrial 0.11.6</strong> ergänzt die Anleitung und bewahrt die Paketverträge. Vorhandene eigene Füllstandsfarben bleiben erhalten; der alte orange Standard wird einmalig rosa.</p><p><strong>Flusspfeile</strong> für Vorlauf, Zirkulation, Warmwasser, Kaltwasser und die dünne kupferfarbene <strong>Ölleitung zum Brenner</strong> sind einzeln abschaltbar. Die rechte Pumpe befindet sich in einer senkrechten Leitung direkt vom Kessel nach oben. Warm- und Kaltwasser bleiben separate Leitungen. Der Tank-Sensor muss Prozent liefern; Liter werden nicht automatisch umgerechnet. Werte außerhalb 0–100 % begrenzen nur die Füllhöhe, der Originalwert bleibt als Zahl sichtbar.</p><p>Fehlende oder ungültige Werte zeigen einen Strich; ein unbekannter Störungszustand zeigt ein Fragezeichen. Ohne Entitäten werden keine Messwerte erfunden. <strong>Beispieldaten ohne Entitäten</strong> sind optional und standardmäßig ausgeschaltet. Das Widget ist eine Anzeige und sendet keine Schaltbefehle. Es besitzt nur Gehäuse-Andockpunkte; Industriestyle, Schrauben, Rahmen und angepasster Hintergrund stehen wie im übrigen Set zur Verfügung.</p><h2 id="blindelement" tabindex="-1">Blindelement <a class="header-anchor" href="#blindelement" aria-label="Permalink to &quot;Blindelement&quot;">​</a></h2><p><img src="'+i+'" alt="Leeres Industriegehäuse mit darüberliegendem Eingabefeld"></p><p>Universelles Hintergrund-Widget als Gehäuse oder gestaltbare Fläche für Widgets aus <strong>allen Widgetsets</strong>. Darüber lassen sich beispielsweise Eingaben, Schalter, Anzeigen und andere Bedienelemente platzieren. Unter <strong>Größe</strong> wählen <strong>Abschnitte</strong> und <strong>Abschnitte senkrecht</strong> jeweils <strong>1 bis 12</strong>: maximal <strong>12:12 Rasterfelder</strong>. Eine Rasterzelle ist mindestens 64×64 px groß. Die Gesamtbreite/-höhe enthält die Zwischenabstände der Einzelwidgets: bei 1 px <strong>Abstand rundherum</strong> ergeben sich pro Richtung <strong>64 / 130 / 196 / 262 px</strong>. Eingabe und Ziehen skalieren beide Richtungen zusammen; eine geänderte Abschnittszahl erhält die Rasterzellengröße.</p><p>Nur die vier einzeln aktivierbaren <strong>Gehäuse-Snappunkte</strong> sind vorhanden. Keine Entität, Wertanzeige oder Daten-Ein-/Ausgänge. Industriestyle, Schrauben, Rahmenfarbe, optional angepasste Rahmenbreite, Eckenradius und CSS stehen wie bei den anderen Industrieelementen zur Verfügung. Der voreingestellte <strong>CSS z-index -1</strong> legt das Blindelement unter normale Widgets. Darübergelegte Elemente bleiben separat bedienbar und verschiebbar; das Blindelement gruppiert sie nicht automatisch. Für eigene Hintergründe lässt sich Industriestyle abschalten und CSS verwenden. Das Bild zeigt ein lokales Beispiel.</p><h2 id="industrie-wetter-lcd-led" tabindex="-1">Industrie-Wetter: LCD / LED <a class="header-anchor" href="#industrie-wetter-lcd-led" aria-label="Permalink to &quot;Industrie-Wetter: LCD / LED&quot;">​</a></h2><table tabindex="0"><thead><tr><th>LCD</th><th>LED</th></tr></thead><tbody><tr><td><img src="'+s+'" alt="Industrie-Wetter in LCD-Optik mit 18,6 Grad und Pixelsymbol"></td><td><img src="'+a+'" alt="Industrie-Wetter mit blau leuchtender LED-Pixelanzeige"></td></tr></tbody></table><p>Die Bilder zeigen Beispieldaten aus einer simulierten Wetterentität. <strong>Wetterentität</strong> bindet eine Home-Assistant-Entität <code>weather.*</code>: Zustand als eigenes Pixelsymbol und Text, Temperatur groß, darunter Luftfeuchtigkeit und Wind. Symbole decken Sonne, klare Nacht, Wolken, Regen, Schnee/Schneeregen, Hagel, Gewitter, Nebel, Wind und außergewöhnliches Wetter ab. Temperatur- und Windeinheiten stammen aus Home Assistant und werden ohne Umrechnung angezeigt; Groß-/Kleinschreibung der Einheiten bleibt erhalten.</p><p><strong>Regenwahrscheinlichkeit anzeigen</strong> und <strong>Tagesminimum/-maximum anzeigen</strong> ergänzen die unterste Zeile, links Regen, rechts Minimum / Maximum. Diese Angaben kommen aus der täglichen Vorhersage für den aktuellen Tag nach Browser-Ortszeit. Vorhersagen werden über die vorhandene HA-Schnittstelle geladen und fünf Minuten zwischengespeichert. Aktuelle Messwerte und Vorhersagen sind bei Home Assistant getrennt; siehe <a href="https://developers.home-assistant.io/docs/core/entity/weather/" target="_blank" rel="noreferrer">HA-Wetterentität und Vorhersagen</a>. Unterstützt die Integration keine tägliche Vorhersage, zeigen die Zusatzwerte Striche, während aktuelle Werte weiter angezeigt werden.</p><p>Unter <strong>Zusätzliche Sensoren</strong> kann jeder Wert durch eine eigene Entität ersetzt werden: Temperatur, Luftfeuchtigkeit, Windgeschwindigkeit, Regenwahrscheinlichkeit, Tagesminimum und Tagesmaximum. Ein eingetragener Sensor hat für diesen Wert Vorrang, auch wenn er nicht verfügbar ist; es wird dann kein anderer Wert untergeschoben. Ohne Sensor gilt die Wetterentität beziehungsweise Tagesvorhersage. Fehlende Werte sind <strong>--</strong>, unbekannter Zustand erhält ein Fragezeichen-Symbol. <strong>Beispieldaten ohne Wetterentität</strong> ist ausdrücklich zuschaltbar und zeigt <strong>DEMO</strong>; bei gebundener Wetterentität wird niemals automatisch auf Beispieldaten umgeschaltet.</p><p><strong>Anzeigeart → LCD / LED</strong>: LCD mit Segment-/Hintergrundfarbe, LED mit frei wählbarer Leuchtfarbe. Der schwarze Bildschirmrand und die Gehäuseeigenschaften entsprechen den übrigen Industrieanzeigen. <strong>2:4-Raster</strong>, standardmäßig <strong>262×130 px</strong> bei <strong>1 px Abstand rundherum</strong>: Höhe = 2 × Rasterzelle + 2 × Abstand, Breite = 4 × Rasterzelle + 6 × Abstand. Die Rasterzelle bleibt mindestens 64 px groß. Eingabe, Ziehen und Abstandsänderungen erhalten die Ausrichtung zu zwei Reihen mit jeweils vier Einzelwidgets. Lange Angaben werden gekürzt; der Tooltip enthält die vollständigen Texte.</p><p>Ein/Aus funktioniert über <strong>Display Ein/Aus: Entität</strong> oder einen einzeln aktivierbaren <strong>oberen Koppelpunkt</strong> (<code>display-power</code>) mit Vorrang. Ohne Bindung gilt der Vorschauzustand; fehlende oder unbekannte Ein/Aus-Werte lassen den Bildschirm dunkel. Sichtbare und unsichtbare Kippschalter-Verbindungen werden unterstützt. Kein Messwert-Eingang, Ausgang oder Schreibbefehl; vier Gehäuse-Ecken, Abstand, Schrauben, Rahmenfarbe, optionale Rahmenbreite und Eckenradius bleiben verfügbar.</p><h2 id="industrie-uhr-nixie-led-lcd" tabindex="-1">Industrie-Uhr: Nixie / LED / LCD <a class="header-anchor" href="#industrie-uhr-nixie-led-lcd" aria-label="Permalink to &quot;Industrie-Uhr: Nixie / LED / LCD&quot;">​</a></h2><p><img src="'+d+'" alt="Industrie-Uhr mit sechs Nixieröhren und orange leuchtender Zeit 12:34:58"></p><table tabindex="0"><thead><tr><th>LED</th><th>LCD</th></tr></thead><tbody><tr><td><img src="'+g+'" alt="Industrie-Uhr mit blauer LED-Leuchtfarbe"></td><td><img src="'+l+'" alt="Industrie-Uhr mit dunklen LCD-Segmenten auf grünem Hintergrund"></td></tr></tbody></table><p>Ein Widget mit <strong>Anzeigeart → Nixieröhre / LED / LCD</strong>. Nixie imitiert Glasröhren, Schutzgitter und übereinanderliegende Drahtziffern mit orangefarbenem Leuchten. LED zeigt leuchtende Siebensegmentziffern mit frei wählbarer <strong>LED-Leuchtfarbe</strong>. LCD bietet <strong>LCD-Segmentfarbe</strong> und <strong>LCD-Hintergrundfarbe</strong>. Die Bilder zeigen eine festgehaltene Beispielzeit.</p><p><strong>Sekunden anzeigen</strong> wechselt zwischen <strong>HH:MM:SS</strong> und <strong>HH:MM</strong>, im 24-Stunden-Format. <strong>Doppelpunkte blinken</strong> lässt die Trennzeichen im Sekundentakt blinken; abschaltbar für ruhige Anzeigen. <strong>Zeitzone</strong> bietet Browser-Ortszeit, UTC oder Europe/Berlin mit automatischer Sommer-/Winterzeit. Zeitquelle ist die Browser-Uhr. Es gibt keine erforderliche Zeit-Entität und keinen Daten-Ausgang. Ein gemeinsamer Takt aktualisiert ausschließlich den Uhrinhalt; Auswahl und Eingabefokus im Editor bleiben erhalten.</p><table tabindex="0"><thead><tr><th>Ansicht</th><th>HH:MM:SS</th><th>HH:MM</th><th>Mindesthöhe</th></tr></thead><tbody><tr><td>Nixie</td><td>518×128 px</td><td>388×128 px</td><td>64 px</td></tr><tr><td>LED / LCD</td><td>262×64 px</td><td>196×64 px</td><td>32 px</td></tr></tbody></table><p>Standardmaße gelten bei <strong>1 px Abstand rundherum</strong>. Die Breite entspricht vier beziehungsweise drei Rastereinheiten einschließlich Zwischenräumen: Breite = Höhe × Rastereinheiten + 2 × Abstand × (Rastereinheiten − 1). Größe bleibt bei Eingabe und Ziehen proportional. Beim Wechsel zu Nixie wird die Höhe verdoppelt, zurück zu LED/LCD halbiert; eine eigene Vergrößerung bleibt relativ erhalten. Sekunden- und Abstandsänderungen passen die Breite an.</p><p>Gehäuse, Schrauben, Rahmenfarbe, optionale Rahmenbreite, Eckenradius und vier einzeln aktive Gehäuse-Snappunkte bleiben verfügbar. <strong>Display Ein/Aus: Entität</strong> oder ein einzeln aktivierbarer <strong>oberer Ein/Aus-Koppelpunkt</strong> (<code>display-power</code>) steuert die Uhranzeige; der Koppelpunkt hat Vorrang. Ohne Bindung gilt <strong>Ohne Eingang eingeschaltet</strong>. Unbekannte oder fehlende Ein/Aus-Werte lassen sie dunkel, Uhrzeit und Gehäuse bleiben erhalten. Kippschalter-Verbindungen können sichtbar oder unsichtbar sein. Die Nixie-Grafiken sind eigene SVG-Zeichnungen; die bereitgestellte OmniGraffle-Vorlage wird nicht verteilt.</p><h2 id="segmentanzeigen-led-und-lcd" tabindex="-1">Segmentanzeigen: LED und LCD <a class="header-anchor" href="#segmentanzeigen-led-und-lcd" aria-label="Permalink to &quot;Segmentanzeigen: LED und LCD&quot;">​</a></h2><table tabindex="0"><thead><tr><th>7-Segment-LED</th><th>16-Segment-LED</th><th>16-Segment-LCD</th></tr></thead><tbody><tr><td><img src="'+o+'" alt="Rote 7-Segment-LED mit 647,25 Watt"></td><td><img src="'+h+'" alt="Blaue 16-Segment-LED mit Eingangswert 56,78 und Ampere-Anzeige"></td><td><img src="'+u+'" alt="Grüne 16-Segment-LCD mit SOLAR 12.3 und Volt-Anzeige"></td></tr></tbody></table><p>Die Bilder verwenden Beispieldaten. Alle drei Anzeigen haben <strong>1–10 feste Stellen</strong>. Das Minuszeichen belegt eine Stelle, ein Dezimalpunkt wird an die vorherige Stelle angehängt. Die 7-Segment-LED zeigt Zahlen mit einstellbaren Nachkommastellen und optionalen führenden Nullen. Rundung erfolgt vor der Prüfung der Stellenzahl; Überlauf oder fehlende Werte zeigen Striche. Die 16-Segment-Anzeigen zeigen Zahlen und Text in Großbuchstaben. Längere Texte werden gekürzt, der vollständige Inhalt steht im Tooltip; nicht unterstützte Zeichen erscheinen als Fragezeichen. Unterstützt werden A–Z, 0–9, Leerzeichen, Punkt, Minus, Unterstrich, Fragezeichen, Plus, Schrägstriche, Doppelpunkt, Gleichheits- und Gradzeichen.</p><p><strong>Inhalt: Entität</strong> liefert den Messwert beziehungsweise Text. Ohne Bindung gilt <strong>Vorschauwert / Text</strong>. Alternativ wird der <strong>Wert-Eingangs-Koppelpunkt links</strong> (<code>value-input</code>) einzeln aktiviert; er hat Vorrang vor der Entität. Ein zweiter, unabhängig aktivierbarer Koppelpunkt <strong>oben</strong> (<code>display-power</code>) oder <strong>Display Ein/Aus: Entität</strong> steuert die Anzeige. Der Ein/Aus-Koppelpunkt hat Vorrang; ohne Bindung gilt <strong>Ohne Eingang eingeschaltet</strong>. Fehlende oder unbekannte Ein/Aus-Werte lassen die Anzeige dunkel. Sichtbare und unsichtbare Wert-Verbindungen funktionieren, beispielsweise vom Kippschalter. Diese Anzeigen haben keine Ausgänge oder Schreibbefehle.</p><p>Rechts stehen <strong>W, A und V untereinander</strong>. Unter <strong>Einheiten-LED</strong> ist ausschließlich <strong>Aus / W / A / V</strong> wählbar: maximal eine Beschriftung leuchtet. Die übrigen bleiben dunkel sichtbar. <strong>Segment- und Einheitenfarbe</strong> gilt für Ziffern, Text und gewählte Einheit gemeinsam. LED-Modi imitieren leuchtende Segmente mit leichtem Lichtschein, LCD verwendet kontrastierende Segmente auf einem einstellbaren Hintergrund. Die Einheit wird bewusst ausgewählt und nicht automatisch aus Entitätsattributen abgeleitet.</p><p>Die Standardgröße beträgt <strong>262×64 px</strong> im <strong>1:4-Raster</strong>, alternativ <strong>196×64 px</strong> im <strong>1:3-Raster</strong>, jeweils bei <strong>1 px Abstand rundherum</strong>. Wie bei Schaltern und linearen Anzeigen gilt: Breite = Höhe × Rastereinheiten + 2 × Abstand × (Rastereinheiten − 1). Eingabe und Ziehen halten das Verhältnis ein. Für zehn gut lesbare Stellen empfiehlt sich 1:4; bei Bedarf lässt sich das ganze Widget vergrößern. Gehäuse, Schrauben, Rahmenfarbe, optionale Rahmenbreite, vier einzeln aktivierbare Gehäuse-Ecken und Abstand bleiben verfügbar.</p><p>Die Segmentgeometrie ist eine eigene SVG-Zeichnung und benötigt keine installierte Schrift. Die bereitgestellte <strong>16Segments Basic.otf</strong> ist laut eingebetteter Lizenz nur privat nutzbar und wird deshalb nicht im öffentlichen Paket verteilt.</p><h2 id="zahlwerk-odometer" tabindex="-1">Zählwerk / Odometer <a class="header-anchor" href="#zahlwerk-odometer" aria-label="Permalink to &quot;Zählwerk / Odometer&quot;">​</a></h2><p>Das Zählwerk ist eine eigenständige, rein lesende Industrieanzeige mit mechanischen Ziffernrollen. Ein Zahlenwert kommt aus einer <strong>Entität</strong> oder über den einzeln aktivierbaren <strong>Eingangs-Koppelpunkt links</strong> (<code>value-input</code>). Der aktivierte Koppelpunkt hat Vorrang; ohne Bindung erscheint der Vorschauwert. Sichtbare und unsichtbare Wert-Verbindungen werden unterstützt. Es gibt keinen Ausgang und keine Schreibbefehle.</p><table tabindex="0"><thead><tr><th>Normal 1:3</th><th>Normal 1:4</th></tr></thead><tbody><tr><td><img src="'+b+'" alt="Zählwerk mit fünf Ganzzahlstellen, zwei Nachkommastellen und kWh"></td><td><img src="'+c+'" alt="Breites Zählwerk mit Eingang über eine Wert-Verbindung"></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Schmal 0,5:3</th><th>Schmal 0,5:4</th></tr></thead><tbody><tr><td><img src="'+m+'" alt="Schmales Zählwerk mit halber Ziffernhöhe"></td><td><img src="'+p+'" alt="Breites schmales Zählwerk"></td></tr></tbody></table><p>Die Bilder verwenden Beispieldaten. Bei <strong>1 px Abstand rundherum</strong> gelten <strong>196×64 / 262×64 px</strong> für normale und <strong>196×32 / 262×32 px</strong> für schmale Widgets. Die Breite enthält die Lücken zwischen drei beziehungsweise vier Einzelwidgets wie bei den linearen Anzeigen. <strong>Breite in Rastereinheiten</strong>, Eingabe, Ziehen und Änderungen des Abstands berücksichtigen diese Ausrichtung.</p><p>Die <strong>Ziffernfensterhöhe</strong> beträgt fest 62,5 % der Widgethöhe: <strong>40 px</strong> bei 64 px, <strong>20 px</strong> bei 32 px. 1:3 und 1:4 nutzen die gleiche Höhe; die schmalen Formate exakt die Hälfte. Mehr Stellen verändern Ziffernbreite und Abstände, nicht die Höhe.</p><p><strong>Ganzzahlstellen</strong> ist fest auf 1–12, <strong>Nachkommastellen</strong> auf 0–6 einstellbar. Das Komma oder der Punkt besitzt einen schmalen Zwischenraum. Beispiel: fünf Ganzzahlstellen und zwei Nachkommastellen ergeben <code>00123,45</code>. Ohne <strong>Führende Nullen</strong> bleiben deren Plätze leer. <strong>Platz für Minuszeichen</strong> reserviert dauerhaft eine Position vor den Ziffern; negative Werte ohne diesen Platz werden als Überlauf behandelt.</p><p>Eine eingetragene <strong>Einheit</strong> hat Vorrang vor <code>unit_of_measurement</code> der Entität beziehungsweise der Einheit der Wert-Verbindung. Die Einheit bleibt rechts neben dem Ziffernfenster. <strong>Schriftfarbe</strong> und <strong>Einheiten-Schriftgröße</strong> sind einstellbar; lange Einheiten werden gekürzt. Industriestyle, standardmäßig aktive Schrauben, Rahmenfarbe, optionale Rahmenbreite, vier einzeln aktive Gehäuse-Ecken und Abstand bleiben verfügbar.</p><p>In der Runtime rollen geänderte Ziffern für 350 ms, einschließlich Übertrag von 09 auf 10. Die Browser-Einstellung für reduzierte Bewegung deaktiviert diese Animation. Fehlende oder nicht verfügbare Werte zeigen <strong>Striche</strong>; ein Wert außerhalb der Stellenzahl zeigt <strong>#</strong>. Rundung erfolgt vor der Überlaufprüfung, beispielsweise wird <code>99999,999</code> bei fünf Ganzzahl- und zwei Nachkommastellen als Überlauf erkannt. Die Breite bleibt dabei konstant.</p><h2 id="linear-gauge-schieberegler" tabindex="-1">Linear-Gauge / Schieberegler <a class="header-anchor" href="#linear-gauge-schieberegler" aria-label="Permalink to &quot;Linear-Gauge / Schieberegler&quot;">​</a></h2><p>Ab <strong>Studio 0.1.241</strong> aktualisiert die Entitätsauswahl sofort den Anzeigemodus: Unter <strong>Skala → Darstellung → Farbbalken</strong> stehen Farbskala und Farbbereiche bereit. Ohne Eingang bleibt ausschließlich Strichskala. Paket 0.6.0 kann weiterverwendet werden.</p><p>Mit <strong>Eingangsentität</strong> oder aktiviertem <strong>Datenfluss-Eingang</strong> arbeitet das Widget als Anzeige: ein <strong>Dreieck</strong> markiert den Wert. Wählbar sind <strong>Strichskala</strong> oder <strong>Farbbalken</strong> mit eigenen Farbbereichen. Ohne Eingang wird es zum <strong>Schieberegler mit rechteckigem Griff und ausschließlich Strichskala</strong>. Auch eine zuvor gespeicherte Farbbalken-Einstellung erzeugt im Schieberegler keinen Farbbalken.</p><table tabindex="0"><thead><tr><th>Schieberegler mit Strichskala</th><th>Linear-Gauge mit Farbbalken</th></tr></thead><tbody><tr><td><img src="'+k+'" alt="Linearer Schieberegler mit rechteckigem Griff und Strichskala"></td><td><img src="'+f+'" alt="Linear-Gauge mit Dreieck und konfigurierten Farbbereichen"></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Schmaler Schieberegler</th><th>Schmales Linear-Gauge</th></tr></thead><tbody><tr><td><img src="'+S+'" alt="Schmale lineare Bedienung mit Strichskala"></td><td><img src="'+z+'" alt="Schmale lineare Anzeige mit Dreieck"></td></tr></tbody></table><p>Die Bilder verwenden Beispieldaten. Unter <strong>Größe → Breite in Rastereinheiten</strong> stehen 2, 3 und 4 zur Auswahl:</p><table tabindex="0"><thead><tr><th>Ausführung</th><th>Höhe/Breite</th><th>Mindestgrößen (Breite × Höhe)</th></tr></thead><tbody><tr><td>Normal</td><td>1:2 / 1:3 / 1:4</td><td>130×64 / 196×64 / 262×64 px</td></tr><tr><td>Schmal</td><td>0,5:2 / 0,5:3 / 0,5:4</td><td>130×32 / 196×32 / 262×32 px</td></tr></tbody></table><p>Die Tabelle gilt für <strong>1 px Abstand rundherum</strong>. Die Gesamtbreite berücksichtigt die Lücken zwischen einzelnen Widgets: <strong>Rasterbreite × Einheiten + 2 × Abstand × (Einheiten − 1)</strong>. Rasterbreite ist die Höhe, bei der schmalen Ausführung die doppelte Höhe. Ohne Abstand ergeben sich 128/192/256 px. Damit fluchten die Außenkanten mit zwei, drei oder vier einzelnen Widgets; Änderungen am Abstand passen die Breite automatisch an.</p><p>Beim Eingeben oder Ziehen werden beide Maße im gewählten Verhältnis skaliert. <strong>Minimum</strong>, <strong>Maximum</strong>, <strong>Skalenteilung</strong> und <strong>Bedien-Schrittweite</strong> sind getrennt einstellbar; negative Werte sind erlaubt, Null wird hervorgehoben. <strong>Skalenwerte anzeigen</strong> ergänzt die Endpunkte und bei freiem Platz Null. Für den Farbbalken gelten die gleichen bis zu acht Farbbereiche wie beim Gauge/Poti. Ungültige Bereiche zeigen keine erfundenen Farben; fehlende Eingangswerte zeigen keinen Zeiger.</p><p>Die Wertanzeige übernimmt Einheit und Schriftgestaltung wie beim Gauge/Poti. <strong>Mitte</strong> platziert sie mittig oberhalb der linearen Skala, <strong>Unten</strong> unterhalb. Industriestyle, Schrauben, Rahmenfarbe, optionale Rahmenbreite, vier einzeln aktivierbare Gehäuse-Ecken, Abstand und zentrale Koppelpunktfarben gelten ebenfalls.</p><p>In der Runtime lässt sich der Griff mit Maus, Touch oder Tastatur bewegen. Pfeiltasten ändern um einen Bedien-Schritt, Bild auf/ab um zehn Schritte, Pos1/Ende springen zum Minimum/Maximum. Ausgabe erfolgt <strong>beim Loslassen</strong> oder <strong>während des Ziehens</strong>. Eine <code>number</code>-/<code>input_number</code>-Entität oder ein Ausgangspunkt mit sichtbarer/unsichtbarer Wert-Verbindung übernimmt den Wert. Der Editor sendet keine Bedienbefehle. Ein aktivierter Datenfluss-Eingang hat Vorrang vor der Eingangsentität und bleibt auch bei fehlendem Wert im Anzeigemodus.</p><h2 id="lcd-–-20×4-und-16×2" tabindex="-1">LCD – 20×4 und 16×2 <a class="header-anchor" href="#lcd-–-20×4-und-16×2" aria-label="Permalink to &quot;LCD – 20×4 und 16×2&quot;">​</a></h2><p>Die Displays imitieren eine <strong>5×8-Punktmatrix-Schrift</strong> mit schwarzem Bildschirmrand. Die Schrift wird dynamisch aus Bildpunkten aufgebaut und ist Bestandteil von Studio; eine externe Schriftinstallation ist nicht erforderlich. Groß- und Kleinbuchstaben, Zahlen, Satzzeichen, Umlaute, ß, €, °, µ, Ω, Pfeile und ✓ sind enthalten. Nicht unterstützte Zeichen erscheinen als <code>?</code>.</p><table tabindex="0"><thead><tr><th>20×4 Gelb/Weiß</th><th>20×4 Blau/Weiß</th></tr></thead><tbody><tr><td><img src="'+E+'" alt="LCD mit gelbem Hintergrund und weißer Punktmatrix-Schrift"></td><td><img src="'+w+'" alt="LCD mit blauem Hintergrund und weißer Punktmatrix-Schrift"></td></tr></tbody></table><table tabindex="0"><thead><tr><th>16×2 Blau/Weiß</th><th>Display ausgeschaltet</th></tr></thead><tbody><tr><td><img src="'+A+'" alt="LCD mit 16 Zeichen je Zeile und zwei Zeilen"></td><td><img src="'+D+'" alt="Ausgeschaltetes LCD mit sichtbarem Industriegehäuse"></td></tr></tbody></table><p>Die Bilder zeigen Beispieldaten. <strong>Beide Größen bieten Gelb/Weiß und Blau/Weiß.</strong> Ab <strong>Studio 0.1.242</strong> ist das 16×2-Display normal groß mit <strong>192×64 px</strong>; das 20×4-Display doppelt so breit und hoch mit <strong>384×128 px</strong>. Beide behalten Höhe/Breite <strong>1:3</strong> beim Eingeben und Ziehen. Kleinere gespeicherte Displays werden beim Laden auf diese Mindestgrößen angehoben. Größere Darstellungen skalieren den Bildschirm und die Zeichen gemeinsam. Die blauen und gelben Hintergründe sind dunkler, die weißen Bildpunkte kräftiger. Paket 0.6.0 bleibt unverändert; ein Studio-Update genügt.</p><h3 id="zeilen-und-entitaten" tabindex="-1">Zeilen und Entitäten <a class="header-anchor" href="#zeilen-und-entitaten" aria-label="Permalink to &quot;Zeilen und Entitäten&quot;">​</a></h3><p>Jede der vier beziehungsweise zwei Zeilen hat <strong>eine eigene Entität</strong> mit Entitätsauswahl. <strong>Text / Präfix</strong> steht vor dem Entitätswert; ohne Entität bildet dieses Feld den gesamten festen Zeileninhalt. Beispiel: <code>Temp: </code> + Sensorwert <code>-20.24</code> + automatische Einheit <code>°C</code> ergibt mit einer Nachkommastelle <code>Temp: -20.2 °C</code>.</p><p><strong>Einheit aus Entität</strong> übernimmt <code>unit_of_measurement</code> aus Home Assistant. Eine eingetragene Einheit hat Vorrang. <strong>Nachkommastellen</strong> unterstützt <code>auto</code> oder 0–6 Stellen für Zahlen; Textzustände bleiben Text. Fehlende oder nicht verfügbare Entitätswerte erscheinen als <code>?</code>. Lange Texte werden nach 20 beziehungsweise 16 Zeichen abgeschnitten; der Tooltip enthält die vollständigen Zeilen. Es gibt keinen Zeilenumbruch und keine eigenen Daten-Koppelpunkte für die Zeilen.</p><h3 id="display-ein-aus-und-gehause" tabindex="-1">Display Ein/Aus und Gehäuse <a class="header-anchor" href="#display-ein-aus-und-gehause" aria-label="Permalink to &quot;Display Ein/Aus und Gehäuse&quot;">​</a></h3><p>Ohne Bindung gilt <strong>Ohne Eingang eingeschaltet</strong>. <strong>Display Ein/Aus: Entität</strong> kann beispielsweise eine <code>switch</code>- oder <code>input_boolean</code>-Entität sein. Alternativ <strong>Ein/Aus-Koppelpunkt aktivieren</strong>: Ein einzelner Eingang oben mittig (<code>display-power</code>) übernimmt <code>on/off</code>, <code>true/false</code> oder <code>1/0</code>. Verbinde einen Kippschalter- oder Wippschalter-Ausgang über eine sichtbare oder unsichtbare Wert-Verbindung mit diesem Eingang.</p><p>Der aktivierte Koppelpunkt hat Vorrang vor der Entität. Ohne gültigen Eingang bleibt der Bildschirm dunkel; ein ausgeschaltetes Display zeigt keine Schrift, das Gehäuse bleibt sichtbar. Das LCD liest Zustände und sendet keine Schaltbefehle. Es besitzt <strong>keinen Ausgang</strong>.</p><p>Unter <strong>Gehäuse und Farben</strong> stehen Industriestyle, standardmäßig aktive Schrauben, Rahmenfarbe und optionale Rahmenbreite bereit. Die vier <strong>Gehäuse-Snappunkte an den Ecken</strong> sind einzeln aktivierbar. Abstand rundherum und die zentralen Farben für Eingangs- und Gehäusepunkte gelten wie bei den anderen Industriewidgets. Schriftgröße folgt dem festen Raster; die Schriftfarbe bleibt im gewählten Farbmodus Weiß.</p><h2 id="wippschalter-–-1-bis-4" tabindex="-1">Wippschalter – 1 bis 4 <a class="header-anchor" href="#wippschalter-–-1-bis-4" aria-label="Permalink to &quot;Wippschalter – 1 bis 4&quot;">​</a></h2><p>Ab <strong>Studio 0.1.237</strong> gilt auch beim Wippschalter: <strong>Breite = Höhe × Schalteranzahl + 2 × Abstand rundherum × (Schalteranzahl − 1)</strong>. Bei 64 px Höhe und 1 px Abstand sind die Breiten <strong>64 / 130 / 196 / 262 px</strong>. Schaltermitten und E/A-Anschlüsse fluchten mit einzeln angedockten Widgets. Eingabe und Ziehen berücksichtigen den Abstand. Ein Studio-Update genügt; Paket 0.3.0 bleibt unverändert.</p><p>Ab Paket <strong>0.3.0</strong> und Studio <strong>0.1.235</strong> ist der Wippschalter eine Kopie des Kippschalters mit transparenten PNG-Grafiken. Unter <strong>Schalter 1</strong> bis <strong>Schalter 4 → Schalterfarbe</strong> wird <strong>Weiß/Grau</strong>, <strong>Rot</strong>, <strong>Schwarz</strong> oder <strong>Grün</strong> je Kanal gewählt. Ein Widget kann unterschiedliche Farben kombinieren; die Grafik wechselt mit dem Ein-/Aus-Zustand.</p><p><img src="'+v+'" alt="Vier Wippschalter mit unabhängig gewählten Farben"></p><p>Alle Kippschalter-Eigenschaften gelten auch hier: Beschriftung, zusätzliche Schilder ON/OFF, 1/0, EIN/AUS oder Benutzerdefiniert, LED-Farben, Entitäten, E1–E4/A1–A4, sechs Gehäuse-Snappunkte, Schrauben, Rahmen und Abstand. Das aufgedruckte O/I bleibt Bestandteil der Grafik. Größe 1:1 bis 4:1, mindestens 64 px je Kanal. Bedienung erfolgt nur in der Runtime.</p><h2 id="gauge-poti-daten-und-bedienung" tabindex="-1">Gauge/Poti: Daten und Bedienung <a class="header-anchor" href="#gauge-poti-daten-und-bedienung" aria-label="Permalink to &quot;Gauge/Poti: Daten und Bedienung&quot;">​</a></h2><p>Ab <strong>Studio 0.1.282</strong> steuert der aktive Datenfluss-Ausgang auch Tempo und Richtung einer angeschlossenen SVG-Line. Eine zusätzliche Home-Assistant-Ausgangsentität ist dafür nicht nötig: Das Feld <strong>Ausgang: number/input_number-Entität</strong> bleibt bei rein lokalen Verbindungen leer; ein Startwert wie <code>0</code> gehört ins Vorschauwertfeld. Für Home-Assistant-Schreibaktionen wähle dagegen eine verfügbare <code>number.*</code>- oder <code>input_number.*</code>-Entität.</p><p>Für sichtbar wertabhängiges Tempo: Animation einschalten, <strong>Poti / SVG LineBox-Teiler</strong> beispielsweise auf <strong>10</strong> setzen und automatische Poti-/LineBox-Teileranpassung ausschalten. 10 ergibt 1 Zyklus/s, 20 ergibt 2; 0 steht still, negative Werte laufen rückwärts. Mit Teiler 1 erreichen alle Beträge ab 20 die Höchstgeschwindigkeit. Weitere Details unter <a href="./svg-line">SVG-Line</a>; <a href="./bildergalerie">Editorbild und Animation</a> zeigen den Aufbau.</p><p>Die folgenden Abschnitte zu Skala und Wertanzeige beschreiben Gauge/Poti. Der Kippschalter hat einen eigenen Abschnitt am Ende der Seite.</p><ul><li><strong>Ohne Eingang:</strong> Poti-Bedienung in der Runtime per Maus, Touch oder Tastatur. Startwert und Bedien-Schrittweite sind einstellbar.</li><li><strong>Mit Eingangs-Entität oder Koppelpunkt:</strong> Gauge-Anzeige. Ein aktivierter Koppelpunkt hat Vorrang vor der Entität. Ein fehlender Eingang wird als fehlender Messwert angezeigt.</li><li><strong>Ausgang:</strong> <code>number.*</code> oder <code>input_number.*</code>, beim Loslassen oder während des Ziehens. Geänderte Gauge-Werte werden ebenfalls weitergegeben. Die Entität muss verfügbar und schreibbar sein; Ein- und Ausgangsentität dürfen nicht identisch sein.</li><li><strong>Wert-Lines:</strong> Sichtbare und optisch unsichtbare Verbindungen nutzen den vorhandenen Datenfluss.</li></ul><p>Im Editor sind Bedienung und Schreibaktionen gesperrt; zum Steuern die Runtime öffnen.</p><h2 id="skala-und-farbbereiche" tabindex="-1">Skala und Farbbereiche <a class="header-anchor" href="#skala-und-farbbereiche" aria-label="Permalink to &quot;Skala und Farbbereiche&quot;">​</a></h2><p>Wählbar sind <strong>Strichskala</strong> mit hervorgehobener Null und <strong>Farbring</strong>. Minimum, Maximum, Skalenteilung und unabhängige Bedien-Schrittweite sind einstellbar; negative Grenzen sind möglich.</p><p>Farbbereiche verwenden aufsteigende <strong>Bis-Werte</strong> innerhalb der Skala. Die letzte Farbe endet am Maximum. Für eine Solarleistung von 0 bis 1000 W können vier Bereiche beispielsweise bei <strong>250 / 500 / 750 / 1000</strong> enden. Nach Änderungen der Skalenlimits müssen die Farbgrenzen angepasst werden. Ungültige Grenzen unterdrücken einen geladenen Messwert nicht; eine Warnung bleibt im Tooltip.</p><h2 id="wertanzeige" tabindex="-1">Wertanzeige <a class="header-anchor" href="#wertanzeige" aria-label="Permalink to &quot;Wertanzeige&quot;">​</a></h2><p>Der eigene Eigenschaftenbereich <strong>Wertanzeige</strong> enthält:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td>Wert anzeigen</td><td>Messwert und Einheit im Instrument anzeigen.</td></tr><tr><td>Einheit</td><td>Eigene Einheit, etwa W. Leer übernimmt <code>unit_of_measurement</code> der Home-Assistant-Eingangsentity.</td></tr><tr><td>Position des Wertes</td><td><strong>Mitte</strong> oder <strong>Unten</strong>; unten liegt unterhalb des Poti-Knopfes.</td></tr><tr><td>Schriftgröße (px)</td><td>Standard 12 px; bleibt beim Ändern der Widget-Größe konstant.</td></tr><tr><td>Schriftfarbe</td><td>Einstellbare Farbe, standardmäßig hell.</td></tr></tbody></table><p>Die Wert-/Einheitenanzeige wurde mit Studio 0.1.227 ergänzt, die eigenen Anzeige-Einstellungen mit 0.1.228.</p><h2 id="gehause-und-farben" tabindex="-1">Gehäuse und Farben <a class="header-anchor" href="#gehause-und-farben" aria-label="Permalink to &quot;Gehäuse und Farben&quot;">​</a></h2><p>Ab <strong>Studio 0.1.248</strong> bieten <strong>alle Industrie-Widgets</strong> die Checkbox <strong>Hintergrund anpassen</strong> mit <strong>Gehäuse-Hintergrundfarbe</strong>. Ohne Haken bleibt der bisherige Standardverlauf von dunkelgrau nach anthrazit erhalten. Mit Haken wird eine einheitliche eigene Farbe verwendet; Vorgabe <strong>#263238</strong>. Die Farbauswahl ist nur bei aktiviertem Haken bedienbar. Nach dem Abschalten kehrt der Standardhintergrund zurück, die gewählte Farbe bleibt für später gespeichert. Das gilt für Editor und Runtime, auch wenn Industriestyle abgeschaltet ist. Bildschirm-, LCD-, Segment-, LED- und Skalenfarben werden weiter separat eingestellt. Das Studio-Update genügt auch mit einem älteren installierten Industriepaket; Paket 0.10.3 aktualisiert die Anleitung.</p><p>Ab Studio <strong>0.1.231</strong> steht direkt unter <strong>Industriestyle</strong> die Checkbox <strong>Schrauben aktivieren</strong>. Schrauben sind standardmäßig eingeschaltet und lassen sich bei aktivem Industriestyle separat ausschalten. Erneutes Einschalten von Industriestyle aktiviert auch die Schrauben wieder. Ohne Industriestyle sind keine Schrauben sichtbar und die Checkbox ist deaktiviert.</p><p><strong>Industriestyle</strong> ergänzt vier Schraubenköpfe, den Gehäusehintergrund und den Rahmen. Skalen- und Zeigerfarbe sind getrennt einstellbar. <strong>CSS Allgemein → Eckenradius (px)</strong> steuert die Rahmenrundung.</p><p>Ab Studio 0.1.230 gilt für <strong>Rahmenbreite anpassen</strong>:</p><ul><li><strong>Ohne Haken:</strong> bisherige Rahmenbreite von 2 px.</li><li><strong>Mit Haken:</strong> eigene <strong>Rahmenbreite (px)</strong> von 1 bis 16 px einstellen.</li><li>Der eigene Wert bleibt beim Abschalten gespeichert; der Rahmen bleibt sichtbar.</li></ul><p><strong>Rahmenfarbe</strong> ist separat wählbar. Bei ausgeschaltetem Industriestyle wird kein Gehäuserahmen angezeigt.</p><h2 id="große" tabindex="-1">Größe <a class="header-anchor" href="#große" aria-label="Permalink to &quot;Größe&quot;">​</a></h2><p>Das Widget beginnt bei <strong>64 × 64 px</strong>. Die seit Studio 0.1.226 standardmäßig aktivierte Checkbox <strong>Verhältnis 1:1</strong> hält Breite und Höhe beim Eingeben und Ziehen gleich. Ohne Haken sind die Maße unabhängig, jeweils mindestens 64 px. Erneutes Aktivieren übernimmt das größere Maß für beide Seiten.</p><h2 id="gehause-snappunkte" tabindex="-1">Gehäuse-Snappunkte <a class="header-anchor" href="#gehause-snappunkte" aria-label="Permalink to &quot;Gehäuse-Snappunkte&quot;">​</a></h2><p>Seit Studio 0.1.224 bietet <strong>Gehäuse-Snappunkte</strong> vier einzeln aktivierbare Ecken und einen gemeinsamen Abstand für alle Seiten. Bei je 1 px entsteht eine 2-px-Fuge; einzelne Widgets rasten beim Verschieben ein.</p><p>Die Farbe liegt unter <strong>Einstellungen → Allgemein → Editor und Andockpunkte → Farbe der Gehäuse-Snappunkte</strong>. Signalanschlüsse bleiben getrennt. Automatische Anschlussverlegung an freie Gehäuseseiten folgt später.</p><h2 id="kippschalter-–-1-bis-4" tabindex="-1">Kippschalter – 1 bis 4 <a class="header-anchor" href="#kippschalter-–-1-bis-4" aria-label="Permalink to &quot;Kippschalter – 1 bis 4&quot;">​</a></h2><p>Ab <strong>Studio 0.1.249</strong> gibt es pro Schalter <strong>Schildbeschriftung → Benutzerdefiniert</strong> mit <strong>Text bei AUS</strong> und <strong>Text bei EIN</strong>. Zum Beispiel Überschrift <strong>Pumpe</strong>, AUS-Text <strong>1</strong>, EIN-Text <strong>2</strong>, oder <strong>Kalt/Warm</strong>. Die vier Kanäle haben unabhängige Texte; leere eigene Texte bleiben leer. Lange Schildtexte werden gekürzt, der Tooltip zeigt den vollständigen Text des aktuellen Zustands. Das gilt ebenfalls für den Wippschalter; dessen aufgedruckte O/I-Symbole bleiben in der Grafik. <strong>Nur die Beschriftung ändert sich:</strong> Entitätsaktionen und E-/A-Koppelpunkte bleiben boolesch (<code>false</code>/<code>true</code>); die Texte „1“/„2“ werden nicht als Zahlenwerte ausgegeben und wählen nicht automatisch zwei Entitäten. Vorhandene Schildvarianten bleiben verfügbar. Das Studio-Update genügt mit bestehenden Industriepaketen.</p><p>Ab <strong>Studio 0.1.236</strong> wird beim Kippschalter der Zwischenabstand in die Blockbreite eingerechnet: <strong>Höhe × Schalteranzahl + 2 × Abstand rundherum × (Schalteranzahl − 1)</strong>. Bei 64 px Höhe und 1 px Abstand rundherum sind die Breiten <strong>64 / 130 / 196 / 262 px</strong>. Schaltermitten sowie E/A-Anschlüsse fluchten damit mit einzelnen Widgets darunter. Eingabe und Ziehen berücksichtigen den Zuschlag. Diese Anpassung gilt zunächst nur für den Kippschalter; Wippschalter bleiben unverändert. Ein Studio-Update genügt, Paket 0.3.0 bleibt unverändert.</p><p>Ab Paket <strong>0.2.0</strong> und Studio <strong>0.1.232</strong> stehen ein bis vier unabhängig bedienbare Schalter nebeneinander zur Verfügung. <strong>Anzahl Schalter</strong> legt das Verhältnis Breite/Höhe von <strong>1:1 bis 4:1</strong> fest. Minimum sind 64 px Höhe und 64 px Breite je Kanal; die Maße bleiben beim Eingeben und Ziehen proportional.</p><p><img src="'+x+'" alt="Vier Industrie-Kippschalter mit kleinen LEDs und drei Schildvarianten"></p><p><em>Runtime mit Beispieldaten: eigene Beschriftungen, grüne LEDs und Schilder ON/OFF, 1/0 und EIN/AUS. Ab Studio 0.1.233 stammt der Metallhebel aus der von rockbaer2007 bereitgestellten transparenten PNG und ist in beiden Stellungen vollständig sichtbar. Die LED bleibt eine CSS-Zeichnung. Das Studio-Update genügt; Paket 0.2.0 muss nicht erneut installiert werden.</em></p><p>Jeder Bereich <strong>Schalter 1</strong> bis <strong>Schalter 4</strong> enthält eine feste <strong>Beschriftung</strong>, <strong>Schildbeschriftung</strong> mit <strong>ON/OFF</strong>, <strong>1/0</strong>, <strong>EIN/AUS</strong> oder <strong>Benutzerdefiniert</strong>, Startzustand und eigene LED-Farben für Ein und Aus. Die LED liegt oberhalb der Beschriftung; die Schildtexte ändern sich nicht durch Entitäten. Schriftgröße und Schriftfarbe stehen unter <strong>Beschriftung</strong>.</p><table tabindex="0"><thead><tr><th>Anschluss je Kanal</th><th>Verhalten</th></tr></thead><tbody><tr><td>Eingang: Entität</td><td>Zustand für Hebel und LED. Ohne Eingang wird eine konfigurierte Ausgangsentität als Rückmeldung verwendet.</td></tr><tr><td>Eingangs-Koppelpunkt</td><td>Oben in der jeweiligen Schalterspalte, einzeln aktivierbar; hat Vorrang vor der Entität.</td></tr><tr><td>Ausgang: Entität</td><td>Schaltet <code>switch.*</code>, <code>light.*</code> oder <code>input_boolean.*</code>. Ohne getrennten Ausgang wird eine geeignete Eingangsentity geschaltet.</td></tr><tr><td>Ausgangs-Koppelpunkt</td><td>Unten in der jeweiligen Schalterspalte, einzeln aktivierbar. Liefert den letzten Bedienbefehl als booleschen Wert; vor der ersten Bedienung den aktuellen Zustand.</td></tr></tbody></table><p>Ohne Bindung arbeitet der Schalter lokal. Fehlende Rückmeldung sperrt die Bedienung. Im Editor werden keine Befehle gesendet. Gehäuse-, Schrauben-, Rahmen- und Gehäuse-Snappunkt-Einstellungen gelten auch für dieses Widget. Für den neuen Kippschalter das Paket lokal auf <strong>0.2.0 aktualisieren</strong>; die bestehenden Gauge/Poti-Definitionen bleiben erhalten.</p><h3 id="anschlusse-e1–e4-und-a1–a4" tabindex="-1">Anschlüsse E1–E4 und A1–A4 <a class="header-anchor" href="#anschlusse-e1–e4-und-a1–a4" aria-label="Permalink to &quot;Anschlüsse E1–E4 und A1–A4&quot;">​</a></h3><p>Ab <strong>Studio 0.1.234</strong> heißen die Signalpunkte im Editor <strong>E1–E4</strong> (Eingang oberhalb des jeweiligen Schalters) und <strong>A1–A4</strong> (Ausgang unterhalb). Bei weniger Schaltern erscheinen nur deren Anschlüsse. Die Punkte sind je Schalter einzeln aktivierbar; Eingangs- und Ausgangsfarbe kommen aus den zentralen Editor-Einstellungen. Bestehende Verbindungen bleiben erhalten.</p><p>Unter <strong>Gehäuse-Snappunkte</strong> besitzt der Kippschalter sechs getrennte, einzeln aktivierbare Punkte: vier Ecken sowie <strong>Links Mitte</strong> und <strong>Rechts Mitte</strong>. Zusammen mit den Signalanschlüssen sind damit <strong>8 / 10 / 12 / 14 Punkte</strong> für ein bis vier Schalter verfügbar. Gehäusepunkte dienen dem Einrasten mit dem eingestellten Abstand und verwenden die Gehäuse-Snappunktfarbe; sie übertragen keine Schaltwerte. Punkte und Anschlussbeschriftungen erscheinen nur im Editor. Ein Studio-Update genügt; Paket <strong>0.2.0</strong> bleibt unverändert.</p>',119)])])}const K=B(P,[["render",_]]);export{T as __pageData,K as default};
